#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_timeline_document_candidate.h"
#include <chrono>
#include <cmath>

int main(int argc,char**argv){try{
 if(argc<2||argc>3)throw std::runtime_error("session [component 0..2] required");SessionTimelineDocumentCandidate doc(loadGraph(argv[1]));uint32_t layer=UINT32_MAX;size_t key=SIZE_MAX;unsigned component=argc==3?unsigned(std::stoul(argv[2])):0;if(component>=3)throw std::runtime_error("component outside xyz");
 for(uint32_t i=0;i<doc.graph().elements.size()&&layer==UINT32_MAX;++i){const auto&e=doc.graph().elements[i];if(doc.graph().strings.at(e.type)!="DmeVector3LogLayer")continue;try{KeyTrack track(doc.graph(),e);if(track.values->type!=24||track.values->values.empty())continue;layer=i;key=0;}catch(const std::runtime_error&){}}
 if(layer==UINT32_MAX)throw std::runtime_error("session has no vector3 key layer");const auto&beforeTrack=KeyTrack(doc.graph(),doc.graph().elements[layer]);const int32_t oldTick=wireInt(beforeTrack.times->values[key]);const int32_t nextTick=key+1<beforeTrack.times->values.size()?wireInt(beforeTrack.times->values[key+1]):INT32_MAX;if(nextTick-oldTick<2)throw std::runtime_error("vector key has no room for timing edit");
 std::array<float,3>before{};for(unsigned c=0;c<3;++c)before[c]=wireFloat(beforeTrack.values->values[key],c);const auto wire=beforeTrack.values->values[key].wire;const float changed=before[component]==321.25f?322.25f:321.25f;const int32_t moved=oldTick+1;
 if(!doc.setVectorKeyComponent(layer,key,component,moved,changed)||!doc.dirty())throw std::runtime_error("vector component edit missing");const auto&edited=KeyTrack(doc.graph(),doc.graph().elements[layer]);if(wireFloat(edited.values->values[key],component)!=changed||wireInt(edited.times->values[key])!=moved)throw std::runtime_error("vector component edit did not apply");for(unsigned c=0;c<3;++c)if(c!=component&&wireFloat(edited.values->values[key],c)!=before[c])throw std::runtime_error("vector sibling component changed");
 if(doc.undo()!=2)throw std::runtime_error("vector edit undo failed");const auto&undone=KeyTrack(doc.graph(),doc.graph().elements[layer]);if(undone.values->values[key].wire!=wire||wireInt(undone.times->values[key])!=oldTick||doc.dirty())throw std::runtime_error("vector edit undo did not restore source");if(doc.redo()!=2)throw std::runtime_error("vector edit redo failed");
 const auto path="work/vector-key-roundtrip-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".dmx";doc.saveAs(path.c_str());const auto reopened=loadGraph(path.c_str());const auto&persisted=KeyTrack(reopened,reopened.elements.at(layer));if(wireFloat(persisted.values->values[key],component)!=changed||wireInt(persisted.times->values[key])!=moved)throw std::runtime_error("vector key save/reopen mismatch");for(unsigned c=0;c<3;++c)if(c!=component&&wireFloat(persisted.values->values[key],c)!=before[c])throw std::runtime_error("saved vector sibling component changed");
 const float valueOnly=changed+2.f;if(!doc.setVectorKeyComponent(layer,key,component,moved,valueOnly))throw std::runtime_error("value-only vector edit missing");const auto&valueOnlyTrack=KeyTrack(doc.graph(),doc.graph().elements[layer]);if(wireInt(valueOnlyTrack.times->values[key])!=moved||wireFloat(valueOnlyTrack.values->values[key],component)!=valueOnly)throw std::runtime_error("value-only vector edit moved its key");if(doc.undo()!=1||doc.dirty())throw std::runtime_error("value-only vector edit was not one undo record");const auto&valueOnlyUndo=KeyTrack(doc.graph(),doc.graph().elements[layer]);if(valueOnlyUndo.values->values[key].wire!=persisted.values->values[key].wire||wireInt(valueOnlyUndo.times->values[key])!=moved)throw std::runtime_error("value-only vector undo mismatch");if(doc.redo()!=1||!doc.dirty())throw std::runtime_error("value-only vector redo mismatch");
 bool rejected=false;try{doc.setVectorKeyComponent(layer,key,3,moved,0.f);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("invalid vector component accepted");std::cout<<"document_vector_key_checks=13 layer="<<layer<<" key="<<key<<" component="<<"XYZ"[component]<<" moved_tick="<<oldTick<<"->"<<moved<<" value_only_tick_preserved=true one_record_undo=true siblings_preserved=true save_reload=true\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
